// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        // log receiver the fuzzer's scenario points c at
        Logger lg = new Logger();
        c.SetLogFile(address(lg));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: the log endpoint configured via SetLogFile(x) is the one
        // that records every subsequent Put. The reference logs into x; the
        // mutant logs into x+1, leaving x with no record.
        assertTrue(lg.count() == 1);
    }
}

contract Logger {
    uint256 public count;
    function AddMessage(address, uint256, string memory) public { count++; }
}
